import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { generateCAM, downloadCAM, listCAMFiles } from '../api/api';
import SimpleButton from '../components/SimpleButton';

const SimpleCAMPreview = () => {
  const navigate = useNavigate();
  const [camFiles, setCamFiles] = useState([]);
  const [generating, setGenerating] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    const loadCAMFiles = async () => {
      try {
        const response = await listCAMFiles();
        if (response.status === 'success') {
          setCamFiles(response.files || []);
        }
      } catch (err) {
        setError('Failed to load CAM files: ' + err.message);
      }
    };

    loadCAMFiles();
  }, []);

  const handleGenerateCAM = async () => {
    setGenerating(true);
    setError('');

    try {
      const response = await generateCAM();
      if (response.status === 'success') {
        // Reload the files list
        const filesResponse = await listCAMFiles();
        if (filesResponse.status === 'success') {
          setCamFiles(filesResponse.files || []);
        }
      }
    } catch (err) {
      setError('Failed to generate CAM: ' + err.message);
    } finally {
      setGenerating(false);
    }
  };

  const handleDownloadCAM = async (filename, format) => {
    try {
      const response = await downloadCAM(filename);
      if (response.status === 'success') {
        // Create a download link
        const link = document.createElement('a');
        link.href = response.download_url;
        link.download = filename;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
      }
    } catch (err) {
      setError('Failed to download CAM: ' + err.message);
    }
  };

  return (
    <div className="min-h-screen py-8">
      <div className="max-w-7xl mx-auto px-4">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 mb-2">Credit Appraisal Memo (CAM)</h1>
              <p className="text-lg text-gray-600">Generate and download comprehensive credit analysis reports</p>
            </div>
            <div className="flex space-x-3">
              <SimpleButton onClick={() => navigate('/dashboard')} className="bg-blue-600 hover:bg-blue-700">
                Back to Dashboard
              </SimpleButton>
            </div>
          </div>
        </div>

        {/* Executive Summary */}
        <div className="bg-white rounded-lg shadow-md p-8 mb-8">
          <h3 className="text-xl font-bold text-gray-900 mb-6 flex items-center">
            <span className="text-2xl mr-2">📋</span>
            Executive Summary
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-4">
              <div className="bg-blue-50 p-4 rounded-lg">
                <h4 className="font-semibold text-gray-900 mb-2">Borrower Overview</h4>
                <p className="text-sm text-gray-700">
                  Comprehensive analysis of the borrower's financial health, credit history, and risk profile.
                </p>
              </div>
              <div className="bg-green-50 p-4 rounded-lg">
                <h4 className="font-semibold text-gray-900 mb-2">Industry Analysis</h4>
                <p className="text-sm text-gray-700">
                  Evaluation of industry trends, market position, and competitive landscape.
                </p>
              </div>
            </div>
            <div className="space-y-4">
              <div className="bg-yellow-50 p-4 rounded-lg">
                <h4 className="font-semibold text-gray-900 mb-2">Risk Assessment</h4>
                <p className="text-sm text-gray-700">
                  Detailed risk scoring with multiple factors and mitigation strategies.
                </p>
              </div>
              <div className="bg-purple-50 p-4 rounded-lg">
                <h4 className="font-semibold text-gray-900 mb-2">Recommendation</h4>
                <p className="text-sm text-gray-700">
                  Clear lending decision with terms and conditions.
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* Generate CAM Button */}
        <div className="bg-white rounded-lg shadow-md p-8 mb-8">
          <div className="text-center">
            <h3 className="text-xl font-bold text-gray-900 mb-6">Generate New CAM Report</h3>
            <p className="text-gray-600 mb-6">
              Create a comprehensive Credit Appraisal Memo with all analysis results
            </p>
            <SimpleButton
              onClick={handleGenerateCAM}
              disabled={generating}
              loading={generating}
              size="lg"
              className="bg-green-600 hover:bg-green-700"
            >
              {generating ? 'Generating CAM...' : 'Generate CAM Report'}
            </SimpleButton>
          </div>
        </div>

        {/* Error Message */}
        {error && (
          <div className="mb-6 bg-red-50 border border-red-200 rounded-lg p-4 flex items-center space-x-3">
            <span className="text-2xl">⚠️</span>
            <p className="text-red-800">{error}</p>
          </div>
        )}

        {/* Existing CAM Files */}
        {camFiles.length > 0 && (
          <div className="bg-white rounded-lg shadow-md p-8">
            <h3 className="text-xl font-bold text-gray-900 mb-6 flex items-center">
              <span className="text-2xl mr-2">📁</span>
              Generated CAM Files
            </h3>
            <div className="space-y-4">
              {camFiles.map((file, index) => (
                <div
                  key={index}
                  className="flex items-center justify-between p-4 bg-gray-50 rounded-lg border border-gray-200"
                >
                  <div className="flex items-center space-x-3">
                    <div className="text-2xl">
                      {file.type === 'Word' ? '📄' : '📕'}
                    </div>
                    <div>
                      <p className="font-medium text-gray-900">{file.filename}</p>
                      <p className="text-sm text-gray-500">{file.size} bytes</p>
                    </div>
                  </div>
                  <div className="flex space-x-2">
                    <SimpleButton
                      onClick={() => handleDownloadCAM(file.filename, 'word')}
                      size="sm"
                      className="bg-blue-600 hover:bg-blue-700"
                    >
                      Download {file.type}
                    </SimpleButton>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {camFiles.length === 0 && (
          <div className="bg-white rounded-lg shadow-md p-8">
            <div className="text-center py-12">
              <div className="text-6xl mb-4">📄</div>
              <h3 className="text-xl font-semibold text-gray-900 mb-2">No CAM Files Generated Yet</h3>
              <p className="text-gray-600 mb-6">
                Generate your first Credit Appraisal Memo to get started
              </p>
              <SimpleButton
                onClick={handleGenerateCAM}
                disabled={generating}
                loading={generating}
                className="bg-green-600 hover:bg-green-700"
              >
                {generating ? 'Generating...' : 'Generate First CAM'}
              </SimpleButton>
            </div>
          </div>
        )}

        {/* Navigation */}
        <div className="mt-8 flex justify-center space-x-4">
          <SimpleButton onClick={() => navigate('/dashboard')} className="bg-gray-600 hover:bg-gray-700">
            Back to Dashboard
          </SimpleButton>
          <SimpleButton onClick={() => navigate('/research')} className="bg-blue-600 hover:bg-blue-700">
            View Research
          </SimpleButton>
        </div>
      </div>
    </div>
  );
};

export default SimpleCAMPreview;
